'use strict';
const C=window.AFTERLIGHT,$=id=>document.getElementById(id),fmt=n=>(n/1000).toFixed(1)+' KB',short=s=>s.slice(0,7)+'…'+s.slice(-6);
const recordedLive=C.deployment.status==='live';
let current=0,verified=null,wallet=null,reading=false,viewEpoch=0,blobUrl=null,toastTimer,chainReady=false,collectionSealed=false;
function toast(s){$('toast').textContent=s;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),4000)}
function save(bytes,name,mime){const url=URL.createObjectURL(new Blob([bytes],{type:mime}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000)}
function info(eyebrow,title,content){$('info-eyebrow').textContent=eyebrow;$('info-title').textContent=title;$('info-content').replaceChildren(content);if(!$('info-dialog').open)$('info-dialog').showModal()}
function p(text){const el=document.createElement('p');el.textContent=text;return el}function button(text,fn,cls='button primary full'){const b=document.createElement('button');b.className=cls;b.textContent=text;b.onclick=fn;return b}
function deployPanel(){if(recordedLive){networkPanel();return}const box=document.createElement('div');box.append(p('The artwork, contract, and uploader are ready. Nothing is represented as minted until its transaction is confirmed on testnet.'));box.append(p('Dedicated testnet deployment address:'));const code=document.createElement('code');code.textContent=C.deployment.contractId;box.append(code,button('Copy deployment address',()=>navigator.clipboard.writeText(C.deployment.contractId).then(()=>toast('Address copied')).catch(()=>toast('Select and copy the address above.')),'button outline full'));box.append(p('This address needs testnet tokens to pay the upload Mana. Do not send mainnet KOIN. Funding does not automatically publish the collection; the resumable uploader must then be run.'));const a=document.createElement('a');a.href='https://t.me/KoinosTestnetFaucetBot';a.target='_blank';a.rel='noopener noreferrer';a.textContent='Open the testnet faucet';a.className='text-link';box.append(a,p('Faucet command: /faucet '+C.deployment.contractId));info('DEPLOYMENT STATUS','Ready for the first block.',box)}
function networkPanel(){const d=document.createElement('div');d.append(p(C.deployment.network),p('Contract: '+C.deployment.contractId),p('RPC: '+C.deployment.rpc));if(C.deployment.totalRcUsed)d.append(p('Collection publication used '+(Number(C.deployment.totalRcUsed)/1e8).toFixed(4)+' Mana.'));d.append(p(chainReady?'The collection can be read from the connected node.':'The collection was verified after publication. The current node connection is not confirmed.'),button('Check the node again',async()=>{await detectChain();networkPanel()},'button outline full'));for(const[label,path]of [['Verification report','chain-verification.json'],['Contract interface','afterlight.abi.json']]){const a=document.createElement('a');a.href=path;a.target='_blank';a.rel='noopener noreferrer';a.textContent=label;a.className='text-link';d.append(p(''),a)}d.append(p('Testnet can reset. The independent viewer can use another compatible node.'));info('NETWORK','Read it from Koinos.',d)}
function renderGallery(){const grid=$('gallery');for(const a of C.items){const b=document.createElement('button');b.className='art-card';b.setAttribute('aria-label','Explore '+a.name);const f=document.createElement('div');f.className='art-frame';const img=document.createElement('img');img.src=a.file;img.alt=a.description;img.width=1000;img.height=1000;if(a.id>3)img.loading='lazy';const n=document.createElement('span');n.className='art-index';n.textContent=String(a.id).padStart(2,'0')+' / 06';const open=document.createElement('span');open.className='art-open';open.textContent='Explore artifact';f.append(img,n,open);const caption=document.createElement('div');caption.className='art-caption';const h=document.createElement('h3');h.textContent=a.name;const e=document.createElement('span');e.textContent='1 / 1';caption.append(h,e);const sub=document.createElement('div');sub.className='art-sub';const el=document.createElement('span');el.textContent=a.element+' · '+a.material;const size=document.createElement('span');size.textContent=fmt(a.bytes);sub.append(el,size);b.append(f,caption,sub);b.onclick=()=>openArtifact(a.id-1);grid.append(b)}$('total-size').textContent=(C.totalBytes/1000).toFixed(0)+' KB';if(C.deployment.totalRcUsed){const cost=p((Number(C.deployment.totalRcUsed)/1e8).toFixed(2)+' Mana to publish the collection');cost.className='small-note';document.querySelector('.proof-strip>div').append(cost)}}
function selectTab(own){$('proof-panel').hidden=own;$('ownership-panel').hidden=!own;$('proof-tab').setAttribute('aria-selected',String(!own));$('ownership-tab').setAttribute('aria-selected',String(own));}
function openArtifact(index){current=(index+6)%6;viewEpoch++;verified=null;if(blobUrl){URL.revokeObjectURL(blobUrl);blobUrl=null}const a=C.items[current];$('detail-image').src=a.file;$('detail-image').alt=a.description;$('detail-number').textContent='ARTIFACT '+String(a.id).padStart(2,'0')+' / 06';$('detail-name').textContent=a.name;$('detail-thought').textContent=a.thought;$('detail-description').textContent=a.description;$('detail-size').textContent=fmt(a.bytes)+' · WebP';$('detail-hash').textContent=a.sha256;$('detail-status').textContent=chainReady?'Checking ownership…':recordedLive?'Node not yet checked':'Not uploaded yet';$('image-source').textContent=recordedLive?'WEBSITE COPY':'WEBSITE PREVIEW';$('download-art').textContent=recordedLive?'Download artwork copy':'Download artwork preview';$('verification-output').textContent='';$('verification-output').className='verification-output';$('verify-button').disabled=reading;$('detail-traits').replaceChildren(...[a.element,a.material,'One of one'].map(t=>{const s=document.createElement('span');s.className='trait';s.textContent=t;return s}));$('owner-text').textContent=chainReady||recordedLive?'Reading the owner from the contract…':'This artifact has not been minted yet. Its owner will appear here after deployment.';$('transfer-form').hidden=true;$('claim-button').hidden=false;selectTab(false);if(!$('artifact-dialog').open)$('artifact-dialog').showModal();if(chainReady||recordedLive)refreshOwner();}
async function refreshOwner(){const epoch=viewEpoch,a=C.items[current];try{const r=await AfterlightChain.read(C.deployment,'owner_of',[[1,new TextEncoder().encode(String(a.id))]]);if(epoch!==viewEpoch)return;const owner=AfterlightChain.base58(r[1]||new Uint8Array());$('detail-status').textContent=owner?'Minted on testnet':'Owner unavailable';$('owner-text').textContent=owner===C.deployment.contractId?'This artifact is available for its first collector.':'Current owner: '+owner;$('claim-button').hidden=owner!==C.deployment.contractId||wallet?.address===C.deployment.contractId;$('claim-button').disabled=!collectionSealed;$('transfer-form').hidden=!wallet||owner!==wallet.address;}catch(e){if(epoch!==viewEpoch)return;$('detail-status').textContent='Not minted or node unavailable';$('owner-text').textContent=e.message;}}
async function verifyCurrent(){if(reading)return;reading=true;$('verify-button').disabled=true;$('verification-output').className='verification-output';const epoch=viewEpoch,a=C.items[current];try{const r=await AfterlightChain.reconstruct(C.deployment,a.id,a.sha256,(i,n)=>{if(epoch===viewEpoch)$('verification-output').textContent=`Reading from Koinos · ${i} of ${n} pieces`;});if(epoch!==viewEpoch)return;verified=r;if(blobUrl)URL.revokeObjectURL(blobUrl);blobUrl=URL.createObjectURL(new Blob([r.bytes],{type:r.mime}));$('detail-image').src=blobUrl;$('image-source').textContent='RECONSTRUCTED FROM KOINOS';$('verification-output').textContent=`Verified. ${r.bytes.length.toLocaleString()} bytes read from the chain. The image fingerprint matches.`;$('download-art').textContent='Download verified chain image';}catch(e){if(epoch===viewEpoch){$('verification-output').className='verification-output error';$('verification-output').textContent=e.message}}finally{reading=false;$('verify-button').disabled=false;}}
async function connect(){if(wallet){const box=document.createElement('div');box.append(p('Connected wallet: '+wallet.address),button('Disconnect',()=>{wallet=null;$('wallet-button').textContent='Connect wallet';$('info-dialog').close();if($('artifact-dialog').open)refreshOwner()},'button outline full'));info('YOUR WALLET','Connected to Kondor.',box);return}const box=document.createElement('div');box.append(p('Use Kondor in a supported desktop browser. Select the Koinos Foundation testnet before signing. The website does not collect recovery phrases or private keys.'),p('On mobile you can explore, download, and verify every artifact. Wallet actions need a browser with the Kondor extension.'),button('Connect with Kondor',async()=>{try{const m=await import('./wallet.js');const accounts=await m.connectWallet(C.deployment);if(!accounts.length)throw Error('No wallet account selected.');const select=document.createElement('select');for(const a of accounts){const o=document.createElement('option');o.value=a.address;o.textContent=(a.name||'Account')+' · '+short(a.address);select.append(o)}const area=document.createElement('div');area.append(p('Choose the account to use for this collection.'),select,button('Use selected account',()=>{wallet=accounts.find(a=>a.address===select.value);$('wallet-button').textContent=short(wallet.address);$('info-dialog').close();toast('Wallet connected');if($('artifact-dialog').open&&chainReady)refreshOwner()}));info('SELECT ACCOUNT','Your collection wallet.',area);}catch(e){toast(e.message)}}));info('KOINOS TESTNET','Connect your wallet.',box)}
async function action(method,recipient){if(!chainReady&&recordedLive)await detectChain();if(!chainReady){deployPanel();return}if(method==='claim'&&!collectionSealed){toast('Claims open after the collection upload is sealed.');return}if(!wallet){connect();return}const a=C.items[current],box=document.createElement('div');box.append(p(method==='claim'?`Claim ${a.name} as a test NFT. Your wallet pays its Mana. There is no purchase price.`:`Transfer ${a.name} to ${recipient}. Check the recipient carefully; confirmed transfers cannot be undone.`),button('Review in wallet',async()=>{try{const m=await import('./wallet.js');const args=method==='claim'?{to:wallet.address,token_id:'0x3'+a.id}:{from:wallet.address,to:recipient,token_id:'0x3'+a.id};const tx=await m.sendAction(C.deployment,wallet.address,method,args);$('info-content').replaceChildren(p('Submitted. Waiting for the chain to confirm this transaction.'),p('Transaction: '+tx.id));try{await tx.wait('byBlock',20000);$('info-content').replaceChildren(p('Included in a block. Ownership will update below. Finality takes additional blocks.'));await refreshOwner()}catch{ $('info-content').replaceChildren(p('Submitted, but confirmation is taking longer. Do not send it again yet. Check ownership after a moment.'),p('Transaction: '+tx.id));}}catch(e){toast(e.message)}}));info('WALLET CONFIRMATION',method==='claim'?'Collect this artifact.':'Transfer this artifact.',box)}
async function detectChain(){try{await AfterlightChain.checkNetwork(C.deployment);const s=await AfterlightChain.read(C.deployment,'get_status');chainReady=true;const minted=Number(s[1]||0n),sealed=s[2]===1n;collectionSealed=sealed;$('deployment-notice').querySelector('.notice-label').textContent=sealed?'LIVE ON TESTNET':'UPLOAD IN PROGRESS';$('deployment-notice').querySelector('p').textContent=`${minted} of 6 artifacts minted. ${sealed?'The collection is sealed and ready to explore on-chain.':'Read individual artifacts as their uploads finish.'}`;$('deployment-button').textContent='Network details';$('deployment-button').onclick=networkPanel;if($('artifact-dialog').open)refreshOwner()}catch{chainReady=false;if(recordedLive){$('deployment-notice').querySelector('.notice-label').textContent='NODE UNAVAILABLE';$('deployment-notice').querySelector('p').textContent='All six artifacts were verified after publication. Reconnect to a testnet node to check their current state.';$('deployment-button').textContent='Network details';$('deployment-button').onclick=networkPanel}}}
renderGallery();document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>{b.closest('dialog').close();if(b.closest('dialog').id==='artifact-dialog')viewEpoch++});document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));$('artifact-dialog').addEventListener('close',()=>viewEpoch++);$('proof-tab').onclick=()=>selectTab(false);$('ownership-tab').onclick=()=>selectTab(true);$('previous-art').onclick=()=>openArtifact(current-1);$('next-art').onclick=()=>openArtifact(current+1);$('verify-button').onclick=verifyCurrent;$('open-proof').onclick=()=>openArtifact(0);$('deployment-button').onclick=recordedLive?networkPanel:deployPanel;$('wallet-button').onclick=connect;$('claim-button').onclick=()=>action('claim');$('transfer-form').onsubmit=e=>{e.preventDefault();action('transfer',$('recipient').value.trim())};$('download-art').onclick=async()=>{const a=C.items[current];if(verified)save(verified.bytes,a.slug+'.webp',verified.mime);else{const r=await fetch(a.file);if(!r.ok){toast('Image download unavailable');return}save(await r.arrayBuffer(),a.slug+'.webp','image/webp')}};$('download-viewer').onclick=async()=>{const r=await fetch('recovery.html');if(!r.ok){toast('Viewer download unavailable');return}save(await r.text(),'AFTERLIGHT-independent-viewer.html','text/html')};$('manifest-button').onclick=()=>save(JSON.stringify(C,null,2),'AFTERLIGHT-manifest.json','application/json');detectChain();
if(document.modelContext?.registerTool){const controller=new AbortController();const tools=[{name:'list_afterlight_artifacts',description:'List the six AFTERLIGHT artifacts and observed deployment status.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({network:C.deployment.network,chainAvailable:chainReady,artifacts:C.items.map(a=>({id:a.id,name:a.name,bytes:a.bytes,sha256:a.sha256}))})},{name:'view_afterlight_artifact',description:'Open an artifact in the gallery. Does not mint, claim, or transfer it.',inputSchema:{type:'object',properties:{artifactId:{type:'integer',minimum:1,maximum:6}},required:['artifactId'],additionalProperties:false},annotations:{readOnlyHint:true},execute:input=>{if(!Number.isInteger(input.artifactId)||input.artifactId<1||input.artifactId>6)throw Error('Artifact ID must be 1 through 6');openArtifact(input.artifactId-1);return{id:input.artifactId,name:C.items[input.artifactId-1].name}}}];for(const tool of tools)try{Promise.resolve(document.modelContext.registerTool(tool,{signal:controller.signal})).catch(()=>{})}catch{}window.addEventListener('pagehide',()=>controller.abort(),{once:true})}
